$ErrorActionPreference='Stop';$root=Join-Path $env:LOCALAPPDATA ('Temp\twwater-claim-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root|Out-Null;$helper=Join-Path $PSScriptRoot 'claim-replacement-candidate.ps1'
try{$a=Join-Path $root 'a.tmp';[IO.File]::WriteAllText($a,'a');$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File $helper -CandidatePath $a;if($LASTEXITCODE-ne0 -or($out -join '')-ne'DELETED' -or(Test-Path $a)){throw 'unlocked delete failed'}
$b=Join-Path $root 'b.tmp';[IO.File]::WriteAllText($b,'b');$lock=[IO.File]::Open($b,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{$ignored=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File $helper -CandidatePath $b;if($LASTEXITCODE-eq0 -or-not(Test-Path $b)){throw 'locked candidate was deleted'}}finally{$lock.Dispose()};$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File $helper -CandidatePath $b;if($LASTEXITCODE-ne0 -or(Test-Path $b)){throw 'post-unlock delete failed'};Write-Output '[OK] Exclusive candidate DeleteOnClose claim passed.'}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}
